-- 72 Scrap Yard: the crane runs to a spot and drops a piece of junk. Every
-- piece is a prefab with a sprite_collider: its collider is the outline of
-- its sprite, traced once its pixels load, so the heap settles by the
-- junk's real shapes. The oldest pieces are cleared as new ones fall.
-- Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/72-scrap-yard.scene"
local JUNK = { "Sy_bicycle", "Sy_kettle", "Sy_gear", "Sy_tyre", "Sy_chair", "Sy_anvil", "Sy_lamp", "Sy_pipe" }
local MAX = 34
local captions = true
local trolley, cable, magnet
local x, target, wait = 0, 0, 0.6
local pieces = {}
local next_kind = 1

function init(entity)
    trolley = Entity.find_by_name("Trolley")
    cable = Entity.find_by_name("Cable")
    magnet = Entity.find_by_name("Magnet")
    math.randomseed(72)
    target = -300
end

local function drop()
    local e = Entity.spawn_prefab(JUNK[next_kind])
    next_kind = next_kind % #JUNK + 1
    Transform.set_position(e, x + (math.random() - 0.5) * 10, 110)
    Transform.set_rotation(e, (math.random() - 0.5) * 0.8)
    Physics.set_angular_velocity(e, (math.random() - 0.5) * 1.5)
    pieces[#pieces + 1] = e
    if #pieces > MAX then
        Entity.destroy(table.remove(pieces, 1))
    end
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    -- Run to the target, wait, drop, pick a new target.
    local d = target - x
    local step = 260 * dt
    if math.abs(d) > step then
        x = x + (d > 0 and step or -step)
    else
        x = target
        wait = wait - dt
        if wait <= 0 then
            drop()
            target = -470 + math.random() * 940
            wait = 0.5
        end
    end
    Transform.set_position(trolley, x, 278)
    Transform.set_position(cable, x, 230)
    Transform.set_position(magnet, x, 170)
end
